GREEN='\033[0;32m'
RED='\033[0;31m'
BLUE='\033[0;34m'
YELLOW='\033[1;33m'
NC='\033[0m'
declare -a FAILED_TESTS=()
RESOURCE_ID='00000000-0000-0000-0000-000000000001'
LAST_STATUS=''
LAST_BODY=''

# Global headers from x-global-headers in 04-api-contract.yaml.
AUTHORIZATION_HEADER="Authorization: Bearer phase4c-test-token"
XTENANTID_HEADER="x-tenant-id: tenant-a"
XSTOREID_HEADER="x-store-id: store-12"
XCORRELATIONID_HEADER="x-correlation-id: corr-ms05-001"
GLOBAL_HEADERS=("${AUTHORIZATION_HEADER}" "${XTENANTID_HEADER}" "${XSTOREID_HEADER}" "${XCORRELATIONID_HEADER}")

extract_field() {
    local json=$1
    local field=$2
    if command -v jq >/dev/null 2>&1; then
        printf '%s' "$json" | jq -r --arg field "$field" '.[$field] // empty'
    else
        python3 -c 'import json,sys; d=json.load(sys.stdin); print(d.get(sys.argv[1], ""))' "$field" <<<"$json"
    fi
}

request() {
    local method=$1 url=$2 payload=$3
    local response
    if [ "$payload" = "null" ]; then
        response=$(curl -sS -w '\n%{http_code}' -X "$method" "$url" "${GLOBAL_HEADERS[@]}")
    else
        response=$(curl -sS -w '\n%{http_code}' -X "$method" "$url" "${GLOBAL_HEADERS[@]}" -H 'Content-Type: application/json' -d "$payload")
    fi
    LAST_STATUS=$(printf '%s\n' "$response" | tail -n 1)
    LAST_BODY=$(printf '%s\n' "$response" | sed '$d')
}

assert_case() {
    local test_num=$1 name=$2 rule_id=$3 method=$4 url=$5 payload=$6 expected=$7 field=${8:-}
    TOTAL=$((TOTAL + 1))
    echo -e "\n${BLUE}Test $test_num: $name${NC}"
    echo "  Rule: $rule_id | $method $url | Expected: $expected"
    request "$method" "$url" "$payload"
    if [ "$LAST_STATUS" = "$expected" ]; then
        if [ -n "$field" ] && [ "$expected" != "204" ]; then
            local value
            value=$(extract_field "$LAST_BODY" "$field")
            if [ -z "$value" ]; then
                echo -e "  ${RED}FAILED${NC}: response field '$field' is missing"
                FAILED=$((FAILED + 1))
                FAILED_TESTS+=("Test $test_num: $name [$rule_id] missing $field")
                return 1
            fi
        fi
        for candidate in id subjectId customerId productId orderId paymentIntentId storeId; do
            local candidate_value
            candidate_value=$(extract_field "$LAST_BODY" "$candidate")
            if [ -n "$candidate_value" ] && [ "$candidate_value" != "null" ]; then
                RESOURCE_ID="$candidate_value"
                break
            fi
        done
        echo -e "  ${GREEN}PASSED${NC} (HTTP $LAST_STATUS)"
        PASSED=$((PASSED + 1))
        return 0
    fi
    echo -e "  ${RED}FAILED${NC} (Expected $expected, got $LAST_STATUS)"
    FAILED=$((FAILED + 1))
    FAILED_TESTS+=("Test $test_num: $name [$rule_id] expected $expected got $LAST_STATUS")
    return 1
}

assert_status() { assert_case "$@"; }
assert_json_field() {
    local test_num=$1 name=$2 rule_id=$3 method=$4 url=$5 payload=$6 field=$7 expected=${8:-200}
    assert_case "$test_num" "$name" "$rule_id" "$method" "$url" "$payload" "$expected" "$field"
}
assert_json_regex() {
    local test_num=$1 name=$2 rule_id=$3 method=$4 url=$5 payload=$6 regex=$7
    TOTAL=$((TOTAL + 1))
    request "$method" "$url" "$payload"
    if printf '%s' "$LAST_BODY" | grep -qE "$regex"; then
        PASSED=$((PASSED + 1))
        return 0
    fi
    FAILED=$((FAILED + 1))
    FAILED_TESTS+=("Test $test_num: $name [$rule_id] regex did not match")
    return 1
}

